// A kaleidoscope: the painting in iTexture0, mirrored into segments around the centre.
// iFloat0 on the timeline is the number of segments.
#define segments iFloat0
#define PI 3.14159265

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Coordinates with (0, 0) in the middle, and y from -1 to 1.
  vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

  // Polar coordinates: the distance from the centre, and the angle, turning slowly.
  float r = length(uv);
  float a = atan(uv.y, uv.x) + 0.15 * iTime;

  // Fold every angle into one segment, mirroring alternate segments.
  float segment = 2.0 * PI / segments;
  a = abs(mod(a, segment) - 0.5 * segment);

  // Back to x and y, then drift slowly across the picture.
  vec2 p = r * vec2(cos(a), sin(a));
  p = 0.45 * p + vec2(0.35, 0.5) + 0.08 * vec2(sin(0.3 * iTime), cos(0.23 * iTime));
  vec3 col = texture(iTexture0, p).rgb;

  // Darken towards the edges.
  col *= 1.0 - smoothstep(0.2, 1.5, r);
  fragColor = vec4(col, 1.0);
}
